import fs from 'fs';
import path from 'path';
import { Command } from 'commander';
import ora from 'ora';
import axios from 'axios';
import { git } from '../utils/git.js';
import { readConfig } from '../utils/config.js';

function recommendVersion(current: string): string {
  const [major, minor, patch] = current.split('.').map(Number);
  return `${major}.${minor}.${patch + 1}`;
}

function parseRepoFromRemote(remoteUrl: string): string | undefined {
  if (!remoteUrl) return;
  // git@github.com:owner/repo.git or https://github.com/owner/repo.git
  const sshMatch = remoteUrl.match(/[:/]([^/]+)\/([^/.]+)(\.git)?$/);
  if (sshMatch) return `${sshMatch[1]}/${sshMatch[2]}`;
  return undefined;
}

async function publishToGitHub(repo: string, tag: string, body: string, draft: boolean) {
  const cfg = readConfig();
  const token = process.env.GITHUB_TOKEN || cfg.tokens?.github;
  if (!token) throw new Error('Missing GITHUB_TOKEN or config.tokens.github');
  const res = await axios.post(
    `https://api.github.com/repos/${repo}/releases`,
    {
      tag_name: tag,
      name: tag,
      body,
      draft
    },
    {
      headers: {
        Authorization: `Bearer ${token}`,
        'User-Agent': 'gitcli',
        Accept: 'application/vnd.github+json'
      },
      timeout: 10_000
    }
  );
  return res.data?.html_url;
}

export function registerRelease(program: Command) {
  const release = program.command('release').description('Release automation');

  release
    .command('create')
    .option('-t, --tag <tag>', 'Release tag')
    .option('--publish', 'Publish release to GitHub')
    .option('--repo <owner/repo>', 'Repository (defaults from git remote origin)')
    .option('--draft', 'Create draft release', false)
    .action(async opts => {
      const spinner = ora('Generating changelog...').start();
      const gitClient = git();
      const log = await gitClient.log({ from: 'HEAD~20', to: 'HEAD' });
      const notes = log.all.map(l => `- ${l.message} (${l.hash.slice(0, 7)})`).join('\n');
      const changelog = `# Changelog\n\n${notes}\n`;
      fs.writeFileSync('CHANGELOG.md', changelog);
      const pkg = JSON.parse(fs.readFileSync('package.json', 'utf8'));
      const nextVersion = opts.tag || recommendVersion(pkg.version);
      spinner.succeed('Changelog created.');
      console.log(`Suggested next version: ${nextVersion}`);
      const manifest = {
        version: nextVersion,
        changelog,
        date: new Date().toISOString()
      };
      fs.writeFileSync('release-manifest.json', JSON.stringify(manifest, null, 2));
      if (opts.publish) {
        try {
          const remote = await gitClient.remote(['get-url', 'origin']);
          const repo = opts.repo || (typeof remote === 'string' ? parseRepoFromRemote(remote.trim()) : undefined);
          if (!repo) throw new Error('Unable to infer repo; pass --repo owner/repo');
          const url = await publishToGitHub(repo, nextVersion, changelog, opts.draft);
          console.log(`Published release to GitHub: ${url || 'unknown URL'}`);
        } catch (err) {
          console.error('Publish failed:', err instanceof Error ? err.message : err);
          console.error('Release manifest written to release-manifest.json; you can upload manually.');
        }
      } else {
        console.log('Release manifest written to release-manifest.json. Run publication steps manually.');
      }
    });
}
